append(name: 'commands.jsonl' | 'observations.jsonl' | 'checkpoints.jsonl', value: unknown) {
  const original = JSON.stringify(value) + '\n'
  const prepared = name === 'observations.jsonl' ? this.observationEncoder.prepare(original) : { text: original, commit: () => {} }
  const text = prepared.text, path = resolve(this.directory, name), bytes = Buffer.byteLength(text)
  // Definition plus reference is one preflighted append; no partial format write.
  assert.ok(lstatSync(path).size + bytes <= COMPACT_CAP, `${name}16MiB cap`)
  this.capacity(bytes); appendFileSync(path, text); prepared.commit()
}

